            ),
        )

class GreedyDamageAgent:
    def __init__(
        self,
        name: str = "Greedy Damage Agent",
    ) -> None:
        self.name = name
        self.last_decision = None

    def choose_move(
        self,
        state: Any = None,
        depth: int | None = None,
        battle_state: Any = None,
        **kwargs: Any,
    ) -> TournamentDecision:
        resolved_state = (
            state
            if state is not None
            else battle_state
        )

        if resolved_state is None:
            raise ValueError(
                "A battle state is required."
            )

        legal_moves = (
            get_current_legal_moves(
                resolved_state
            )
        )

        if not legal_moves:
            self.last_decision = (
                TournamentDecision(
                    move=None,
                    score=0.0,
                    search_depth=int(
                        depth or 0
                    ),
                    nodes=0,
                    confidence=0.0,
                    selected_move_name=None,
                    fallback=True,
                    reason=
                        "No legal moves available.",
                )
            )

            return self.last_decision

        selected_index = max(
            range(
                len(legal_moves)
            ),
            key=lambda index: (
                tournament_move_damage(
                    legal_moves[index]
                ),
                -index,
            ),
        )

        selected_move = (
            legal_moves[
                selected_index
            ]
        )

        maximum_damage = (
            tournament_move_damage(
                selected_move
            )
        )

        self.last_decision = (
            TournamentDecision(
                move=
                    selected_move,

                score=
                    maximum_damage,

                search_depth=int(
                    depth or 0
                ),

                nodes=0,

                confidence=1.0,

                selected_move_name=
                    tournament_move_name(
                        selected_move
                    ),

                fallback=False,
            )
        )

        return self.last_decision

    def get_last_decision(
        self,
    ) -> TournamentDecision | None:
        return self.last_decision

